import type { FastifyRequest, preHandlerHookHandler } from 'fastify';

import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { verifyToken } from './jwt.js';

declare module 'fastify' {
  interface FastifyRequest {
    userId: number | null;
  }
}

/**
 * RealWorld는 `Authorization: Token <jwt>` 스킴을 쓴다. `Bearer`는 인정하지
 * 않는다(스킴 이름만 대소문자 무시).
 */
function parseToken(req: FastifyRequest): string | null {
  const header = req.headers.authorization;
  if (typeof header !== 'string') return null;

  const [scheme, ...rest] = header.trim().split(/\s+/);
  if (scheme?.toLowerCase() !== 'token' || rest.length !== 1) return null;

  return rest[0] ?? null;
}

/** 토큰이 가리키는 사용자가 실제로 남아 있는지까지 확인한다(삭제된 사용자 방어). */
async function resolveUserId(req: FastifyRequest): Promise<number | null> {
  const token = parseToken(req);
  if (token === null) return null;

  const userId = verifyToken(token);
  if (userId === null) return null;

  const user = await prisma.user.findUnique({ where: { id: userId }, select: { id: true } });
  return user ? user.id : null;
}

/** 헤더 없음 / 스킴 불일치 / 토큰 무효 / 사용자 없음 → 전부 401. */
export const requireAuth: preHandlerHookHandler = async (req) => {
  const userId = await resolveUserId(req);
  if (userId === null) throw ApiError.tokenMissing();
  req.userId = userId;
};

/** 같은 실패 조건에서 401을 던지지 않고 익명(userId = null)으로 강등한다. */
export const optionalAuth: preHandlerHookHandler = async (req) => {
  req.userId = await resolveUserId(req);
};

