import type { FastifyPluginAsync } from 'fastify';

import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { requireAuth, optionalAuth } from '../auth/hooks.js';
import { toCommentResponse, toCommentsResponse } from '../serializers/index.js';
import { asCommentInclude, normalizeComment } from '../services/comment-query.js';

type SlugParams = { slug: string };
type SlugIdParams = { slug: string; id: string };

/** 바디 스키마를 붙이지 않으므로(fastify-project-conventions) 여기서 직접 판별한다. */
function commentBody(body: unknown): string {
  const root = typeof body === 'object' && body !== null ? (body as Record<string, unknown>) : {};
  const comment = typeof root.comment === 'object' && root.comment !== null ? root.comment : {};
  const value = (comment as Record<string, unknown>).body;
  if (typeof value !== 'string' || value.trim() === '') throw ApiError.blank('body');
  return value;
}

/** 응답 조립에 쓰지 않는 최소 조회. 존재하지 않으면 404 `article`. */
async function findArticleIdOr404(slug: string): Promise<number> {
  const article = await prisma.article.findUnique({ where: { slug }, select: { id: true } });
  if (article === null) throw ApiError.notFound('article');
  return article.id;
}

/**
 * `:id`는 문자열로 들어온다. 파싱 실패는 "없는 댓글"과 같게 404 `comment`로 다룬다.
 * `Number.parseInt('12abc')`가 12를 내므로 Number()로 엄격 변환한다.
 */
function parseCommentId(raw: string): number {
  const id = Number(raw);
  if (!Number.isInteger(id)) throw ApiError.notFound('comment');
  return id;
}

export const commentsRoutes: FastifyPluginAsync = async (app) => {
  // 검사 순서: 인증 → 바디 검증 → 글 존재. "무인증 + 없는 slug"는 401이다.
  app.post<{ Params: SlugParams }>(
    '/articles/:slug/comments',
    { preHandler: requireAuth },
    async (req, reply) => {
      const authorId = req.userId!;
      const body = commentBody(req.body);
      const articleId = await findArticleIdOr404(req.params.slug);

      const raw = await prisma.comment.create({
        data: { body, articleId, authorId },
        include: asCommentInclude(authorId),
      });

      return reply.code(201).send(toCommentResponse(normalizeComment(raw)));
    },
  );

  app.get<{ Params: SlugParams }>(
    '/articles/:slug/comments',
    { preHandler: optionalAuth },
    async (req) => {
      const viewerId = req.userId;
      const articleId = await findArticleIdOr404(req.params.slug);

      const raws = await prisma.comment.findMany({
        where: { articleId },
        include: asCommentInclude(viewerId),
        // 스펙 미정의. 같은 밀리초 생성분의 순서가 흔들리지 않도록 id를 병기한다.
        orderBy: [{ createdAt: 'asc' }, { id: 'asc' }],
      });

      return toCommentsResponse(raws.map(normalizeComment));
    },
  );

  // 존재(404) → 소유권(403) 순서. 403이면 댓글은 그대로 남아야 한다.
  app.delete<{ Params: SlugIdParams }>(
    '/articles/:slug/comments/:id',
    { preHandler: requireAuth },
    async (req, reply) => {
      const userId = req.userId!;
      const articleId = await findArticleIdOr404(req.params.slug);
      const commentId = parseCommentId(req.params.id);

      const comment = await prisma.comment.findUnique({
        where: { id: commentId },
        select: { id: true, articleId: true, authorId: true },
      });
      // 다른 글에 달린 댓글이면 이 경로에서는 존재하지 않는 것으로 본다.
      if (comment === null || comment.articleId !== articleId) throw ApiError.notFound('comment');
      if (comment.authorId !== userId) throw ApiError.forbidden('comment');

      await prisma.comment.delete({ where: { id: comment.id } });

      return reply.code(204).send();
    },
  );
};

