import { buildApp } from './src/app.js';

const app = buildApp();
const ok: string[] = [];
const bad: string[] = [];
function check(name: string, cond: boolean, extra = '') {
  (cond ? ok : bad).push(`${cond ? 'PASS' : 'FAIL'} ${name} ${cond ? '' : extra}`);
}

const j = (r: { body: string }) => JSON.parse(r.body || '{}');

async function reg(username: string) {
  const r = await app.inject({
    method: 'POST',
    url: '/api/users',
    payload: { user: { username, email: `${username}@x.com`, password: 'bonjour1' } },
  });
  return j(r).user.token as string;
}

const tokenA = await reg(`a${Date.now()}`);
const tokenB = await reg(`b${Date.now()}`);
const usernameA = j(await app.inject({ method: 'GET', url: '/api/user', headers: { authorization: `Token ${tokenA}` } })).user.username;

const art = await app.inject({
  method: 'POST',
  url: '/api/articles',
  headers: { authorization: `Token ${tokenA}` },
  payload: { article: { title: `T${Date.now()}`, description: 'd', body: 'b', tagList: ['x'] } },
});
const slug = j(art).article.slug as string;

const auth = { authorization: `Token ${tokenA}` };
const c1 = await app.inject({ method: 'POST', url: `/api/articles/${slug}/comments`, headers: auth, payload: { comment: { body: 'first' } } });
check('POST 201', c1.statusCode === 201, String(c1.statusCode));
const b1 = j(c1).comment;
check('id integer', typeof b1.id === 'number' && Number.isInteger(b1.id), JSON.stringify(b1.id));
check('author.username == A', b1.author.username === usernameA);
check('following false', b1.author.following === false);

const c2 = await app.inject({ method: 'POST', url: `/api/articles/${slug}/comments`, headers: auth, payload: { comment: { body: 'second' } } });
check('POST 201 (2)', c2.statusCode === 201);

const list = await app.inject({ method: 'GET', url: `/api/articles/${slug}/comments` });
check('GET 200', list.statusCode === 200);
check('no count key', !('commentsCount' in j(list)) && Object.keys(j(list)).join() === 'comments', Object.keys(j(list)).join());
check('anon following false', j(list).comments.every((c: any) => c.author.following === false));
check('order asc', j(list).comments[0].body === 'first');

const del403 = await app.inject({ method: 'DELETE', url: `/api/articles/${slug}/comments/${b1.id}`, headers: { authorization: `Token ${tokenB}` } });
check('B delete 403', del403.statusCode === 403, String(del403.statusCode));
check('403 body', JSON.stringify(j(del403)) === '{"errors":{"comment":["forbidden"]}}', del403.body);
const after403 = j(await app.inject({ method: 'GET', url: `/api/articles/${slug}/comments` }));
check('comment survives 403', after403.comments.length === 2);

const del = await app.inject({ method: 'DELETE', url: `/api/articles/${slug}/comments/${b1.id}`, headers: auth });
check('DELETE 204', del.statusCode === 204, String(del.statusCode));
check('204 empty body', del.body === '', JSON.stringify(del.body));
const after = j(await app.inject({ method: 'GET', url: `/api/articles/${slug}/comments` }));
check('remaining 1 = second', after.comments.length === 1 && after.comments[0].body === 'second');

const blank = await app.inject({ method: 'POST', url: `/api/articles/${slug}/comments`, headers: auth, payload: { comment: { body: '' } } });
check('blank 422', blank.statusCode === 422 && JSON.stringify(j(blank)) === '{"errors":{"body":["can\'t be blank"]}}', blank.body);

const noSlug = await app.inject({ method: 'POST', url: `/api/articles/nope-nope/comments`, headers: auth, payload: { comment: { body: 'x' } } });
check('bad slug 404 article', noSlug.statusCode === 404 && JSON.stringify(j(noSlug)) === '{"errors":{"article":["not found"]}}', noSlug.body);

const noComment = await app.inject({ method: 'DELETE', url: `/api/articles/${slug}/comments/999999`, headers: auth });
check('bad id 404 comment', noComment.statusCode === 404 && JSON.stringify(j(noComment)) === '{"errors":{"comment":["not found"]}}', noComment.body);
const nanId = await app.inject({ method: 'DELETE', url: `/api/articles/${slug}/comments/abc`, headers: auth });
check('non-numeric id 404 comment', nanId.statusCode === 404 && JSON.stringify(j(nanId)) === '{"errors":{"comment":["not found"]}}', nanId.body);

const anonPost = await app.inject({ method: 'POST', url: `/api/articles/nope/comments`, payload: { comment: { body: 'x' } } });
check('anon POST 401 (even bad slug)', anonPost.statusCode === 401, anonPost.body);
const anonDel = await app.inject({ method: 'DELETE', url: `/api/articles/${slug}/comments/1` });
check('anon DELETE 401', anonDel.statusCode === 401, String(anonDel.statusCode));

console.log([...ok, ...bad].join('\n'));
console.log(`\n${ok.length} passed, ${bad.length} failed`);
await app.close();
process.exit(bad.length === 0 ? 0 : 1);

